const j = $input.first().json;
if (!Array.isArray(j.attachments) || j.attachments.length === 0) {
  return [{ json: { ...j, hasAttachment: false } }];
}
return j.attachments.map((a, index) => ({ json: { ...j, attachments: undefined, hasAttachment: true, attachmentIndex: index, attachmentName: a.name, attachmentUrl: a.url, attachmentMimeType: a.mimeType } }));

const items = $input.all();
if (!items.length) return [];
const first = items[0];
const binary = {};
let n = 0;
for (const item of items) {
  if (!item.json.hasAttachment || !item.binary?.data) continue;
  binary['attachment_' + n] = { ...item.binary.data, fileName: item.json.attachmentName || item.binary.data.fileName || ('attachment-' + n), mimeType: item.json.attachmentMimeType || item.binary.data.mimeType || 'application/octet-stream' };
  n++;
}
return [{ json: { cardId:first.json.cardId, cardName:first.json.cardName, cardUrl:first.json.cardUrl, emailSubject:first.json.emailSubject, emailHtml:first.json.emailHtml, attachmentCount:n, alreadySentRecipients:Array.isArray(first.json.alreadySentRecipients) ? first.json.alreadySentRecipients : [] }, binary }];

const item = $input.first();
const attachments = [];
for (const key of Object.keys(item.binary || {})) {
  const meta = item.binary[key];
  const buffer = await this.helpers.getBinaryDataBuffer(0, key);
  const attachment = {};
  attachment['@odata.type'] = '#microsoft.graph.fileAttachment';
  attachment.name = meta.fileName || key;
  attachment.contentType = meta.mimeType || 'application/octet-stream';
  attachment.contentBytes = buffer.toString('base64');
  attachments.push(attachment);
}
const allRecipients = [
  'a.wisniewski@neon-light.eu',
  'jiri.zvolsky@topadvert.cz',
  'shapovalova@goleks.com',
  'max@goleks.com',
  'export@dad.lt',
  'kristel.lembit@luminescence.ee'
];
const alreadySent = new Set((Array.isArray(item.json.alreadySentRecipients) ? item.json.alreadySentRecipients : []).map(value => String(value).toLowerCase()));
const recipients = allRecipients.filter(recipient => !alreadySent.has(recipient.toLowerCase()));
return recipients.map(recipient => {
  const message = {};
  message.subject = item.json.emailSubject;
  message.body = { contentType: 'HTML', content: item.json.emailHtml };
  message.toRecipients = [ { emailAddress: { address: recipient } } ];
  message.attachments = attachments;
  return { json: {
    cardId: item.json.cardId,
    recipient,
    graphBody: { message, saveToSentItems: true }
  } };
});

const sentItem = $('CombineAttachments').first();
const cardId = sentItem.json.cardId;
const state = $getWorkflowStaticData('global');
state.sent = state.sent || {};
state.sent[cardId] = { sentAt:new Date().toISOString(), attachmentCount:sentItem.json.attachmentCount, recipientCount:6 };
delete state.claimed?.[cardId];
delete state.firstSeen?.[cardId];
return [{ json:{ cardId, cardName:sentItem.json.cardName, attachmentCount:sentItem.json.attachmentCount, recipientCount:6 } }];

const root = $input.first().json || {};
const stack = [root];
let extracted = null;
while (stack.length && !extracted) {
  const value = stack.shift();
  if (Array.isArray(value)) {
    for (const nested of value) stack.push(nested);
  } else if (value && typeof value === 'object') {
    if ('dimensions' in value && 'mounting' in value && 'deadline' in value) {
      extracted = value;
      break;
    }
    for (const nested of Object.values(value)) stack.push(nested);
  } else if (typeof value === 'string') {
    const cleaned = value.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
    try {
      const parsed = JSON.parse(cleaned);
      stack.push(parsed);
    } catch (error) {}
  }
}
if (!extracted) throw new Error('Gemini did not return the required supplier data JSON.');
const card = $('RecheckCardWithAttachments').first().json || {};
if (!card.id || card.idList !== '6a4fa373d16787b871c2625b') return [];
const text = (value, fallback) => String(value || fallback).trim();
const esc = value => text(value, '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const dimensions = text(extracted.dimensions, 'See attachment');
const illumination = text(extracted.illumination_colour, 'See logo / attached design');
const paint = text(extracted.paint_colour, 'See logo / attached design');
const mounting = text(extracted.mounting, 'Loose letters');
const quantity = text(extracted.quantity, '1');
const application = text(extracted.application, 'See attachment');
const deadlineCandidate = text(extracted.deadline, 'Not specified');
const normalizeDeadlineText = value => String(value || '').toLowerCase().replace(/\s+/g, ' ').trim();
const descriptionNormalized = normalizeDeadlineText(card.desc);
const deadlineNormalized = normalizeDeadlineText(deadlineCandidate);
const deadlineMissing = /^(not specified|unknown|tbd|n\/?a|-)$/.test(deadlineNormalized);
const deadlineHasBindingCue = /(?:spätestens\s+bis|muss\s+(?:spätestens\s+)?bis|lieferung\s+(?:muss\s+)?(?:spätestens\s+)?bis|benötigt\s+bis|required\s+by|must\s+(?:arrive|be\s+delivered)\s+by|no\s+later\s+than|latest\s+delivery)/i.test(deadlineCandidate);
const deadline = !deadlineMissing && deadlineHasBindingCue && deadlineNormalized && descriptionNormalized.includes(deadlineNormalized) ? deadlineCandidate : '';
const uploads = (Array.isArray(card.attachments) ? card.attachments : []).filter(a => a && a.url && a.isUpload !== false);
const recipientMarkerPrefix = '[Auto][EU-REQUEST-RECIPIENT] ';
const alreadySentRecipients = [...new Set((Array.isArray(card.actions) ? card.actions : []).map(action => String(action?.data?.text || '')).filter(text => text.startsWith(recipientMarkerPrefix)).map(text => text.slice(recipientMarkerPrefix.length).split(/\s+/)[0].trim().toLowerCase()).filter(Boolean))];
const rasterExtensions = new Set(['jpg','jpeg','png','webp','gif','bmp','tif','tiff','heic','heif','avif']);
const attachmentExtension = attachment => {
  const name = String(attachment?.name || '').toLowerCase().split('?')[0].split('#')[0];
  return name.includes('.') ? name.split('.').pop() : '';
};
const hasOnlyRasterImages = uploads.length > 0 && uploads.every(attachment => {
  const extension = attachmentExtension(attachment);
  const mimeType = String(attachment?.mimeType || '').toLowerCase();
  return rasterExtensions.has(extension) || (mimeType.startsWith('image/') && mimeType !== 'image/svg+xml');
});
const missingVectorNote = hasOnlyRasterImages
  ? '<p>We currently do not have a vector file from the customer; could you please still calculate the quotation based on the attached images?</p>'
  : '';
const signature = '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="font-family:Arial,Helvetica,sans-serif;color:#111111;margin-top:30px"><tbody><tr><td><table role="presentation" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;width:100%"><tbody><tr><td style="padding:16px 0"><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%"><tbody><tr><td valign="top" style="width:140px;padding-right:16px"><img src="https://cdn.shopify.com/s/files/1/0534/7819/5350/files/fabienne123.jpg?v=1764000653" alt="Fabienne Trapp" width="120" height="120" style="display:block;width:120px;height:120px;border-radius:60px;border:2px solid #111111;object-fit:cover"></td><td valign="top"><div style="font-size:16px;font-weight:700">Fabienne Trapp</div><div style="font-size:12px;color:#6b7280;margin:4px 0 10px">Beratung &amp; Realisierung</div><div style="font-size:13px;font-weight:700;margin-bottom:8px">NEONTRIP®</div><div style="font-size:13px;line-height:1.6">Tel: +49 211 54257240<br>E-Mail: support@neontrip.de<br>Web: www.neontrip.de<br>Adresse: Bilker Allee 29, 40219 Düsseldorf</div></td></tr></tbody></table></td></tr></tbody></table></td></tr></tbody></table>';
const emailHtml = '<div style="font-family:Arial,Helvetica,sans-serif;color:#111;line-height:1.6"><p>Hello,</p><p>we would like to request a quotation for the following sign:</p><p><strong>Size:</strong> '+esc(dimensions)+'<br><strong>Illumination colour:</strong> '+esc(illumination)+'<br><strong>Paint colour:</strong> '+esc(paint)+'<br><strong>Mounting:</strong> '+esc(mounting)+'<br><strong>Quantity:</strong> '+esc(quantity)+'<br><strong>Application:</strong> '+esc(application)+(deadline ? '<br><strong>Required deadline:</strong> '+esc(deadline) : '')+'</p><p>Please find all available design files attached.</p>'+missingVectorNote+'<p>Please send us your price, production time and shipping time to Germany.</p><p>Thank you.</p></div>'+signature;

return [ { json: { cardId:card.id, cardName:card.name || '', cardUrl:card.url || '', emailSubject:'NEONTRIP | Quotation Request | '+new Intl.DateTimeFormat('de-DE', { timeZone:'Europe/Berlin', day:'2-digit', month:'2-digit', year:'numeric' }).format(new Date()), emailHtml:emailHtml, extracted:extracted, attachments:uploads.map(a => ({ id:a.id, name:a.name || ('attachment-'+a.id), url:a.url, mimeType:a.mimeType || 'application/octet-stream' })), alreadySentRecipients } } ];

const event = $('TrelloMoveTrigger').first().json;
const cardId = event?.action?.data?.card?.id;
if (!cardId) throw new Error('Trello move event did not contain a card ID.');
return [ { json: { cardId: cardId, actionId: event.action.id || null } } ];
